// Loader for the public forward-run file (public/data/self/forward.json). Pure over its input so tests can import it.
import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";

export interface ForwardRow {
  task: string;
  old: boolean;
  new: boolean;
  costOld: number | null;
  costNew: number | null;
  excluded?: string;
}

export interface ForwardSummary {
  n: number;
  wording: string;
  /** Rows that were malformed and left out of `rows`. */
  skipped: number;
}

export interface Forward {
  rows: ForwardRow[];
  summary: (ForwardSummary) | null;
}

const isObj = (v: unknown): v is Record<string, unknown> => typeof v === "object" && v !== null && !Array.isArray(v);
const isCost = (v: unknown): v is number | null => v === null || (typeof v === "number" && Number.isFinite(v) && v >= 0);

function parseRow(v: unknown): ForwardRow | null {
  if (!isObj(v)) return null;
  const { task, old, new: nw, costOld, costNew, excluded } = v;
  if (typeof task !== "string" || task === "") return null;
  if (typeof old !== "boolean" || typeof nw !== "boolean") return null;
  if (!isCost(costOld) || !isCost(costNew)) return null;
  if (excluded !== undefined && typeof excluded !== "string") return null;
  const row: ForwardRow = { task, old, new: nw, costOld, costNew };
  if (excluded !== undefined) row.excluded = excluded;
  return row;
}

/** Accepts `{ rows, summary }`. Malformed rows are skipped and counted in summary.skipped. Anything else gives the empty result. */
export function loadForward(json: unknown): Forward {
  if (!isObj(json) || !Array.isArray(json.rows)) return { rows: [], summary: null };
  const rows: ForwardRow[] = [];
  let skipped = 0;
  for (const r of json.rows) {
    const p = parseRow(r);
    if (p) rows.push(p);
    else skipped++;
  }
  const s = json.summary;
  let summary: ForwardSummary | null = null;
  if (isObj(s) && typeof s.wording === "string" && typeof s.n === "number" && Number.isFinite(s.n)) {
    summary = { n: s.n, wording: s.wording, skipped };
  }
  return { rows, summary };
}

function readJson(file: string): unknown {
  if (!existsSync(file)) return null;
  try {
    return JSON.parse(readFileSync(file, "utf8"));
  } catch {
    return null;
  }
}

const SELF = (dataDir: string) => join(dataDir, "self");

/** Reads forward.json from dataDir/self (default public/data). Absent or unreadable gives the empty result. */
export function readForward(dataDir = join(process.cwd(), "public", "data")): Forward {
  return loadForward(readJson(join(SELF(dataDir), "forward.json")));
}

/** The backlog sha256 from prereg.json, or null when the file is absent or has none. */
export function readBacklogSha(dataDir = join(process.cwd(), "public", "data")): string | null {
  const j = readJson(join(SELF(dataDir), "prereg.json"));
  if (!isObj(j)) return null;
  const v = j.backlog_sha256 ?? j.backlogSha256 ?? j.sha256;
  return typeof v === "string" && v !== "" ? v : null;
}

import type { Metadata } from "next";
import { GITHUB } from "@/components/LandingData";
import { readBacklogSha, readForward } from "@/lib/forward";

export const metadata: Metadata = {
  title: "Experiment · Roster",
  description: "The pre-registration and the forward run, paired old vs new, as it fills in.",
};

const mark = (b: boolean) => (b ? "pass" : "fail");
const cost = (c: number | null) => (c === null ? "unknown" : `$${c.toFixed(2)}`);

export default function Experiment() {
  const { rows, summary } = readForward();
  const sha = readBacklogSha();
  return (
    <>
      <h1>Experiment</h1>
      <p className="lede">Tasks were registered before the setups were picked, then run through both setups.</p>
      <p className="meta">
        Pre-registration:{" "}
        <a href={`${GITHUB}/blob/main/experiments/PREREGISTRATION.md`}>experiments/PREREGISTRATION.md</a>
      </p>
      {sha && (
        <p className="meta">
          Backlog sha256: <code>{sha}</code>
        </p>
      )}
      {rows.length === 0 ? (
        <div className="empty">The forward run has not started</div>
      ) : (
        <div className="scroll">
          <table className="compact">
            <thead>
              <tr>
                <th>Task</th>
                <th>Old</th>
                <th>New</th>
                <th>Old cost</th>
                <th>New cost</th>
                <th>Excluded</th>
              </tr>
            </thead>
            <tbody>
              {rows.map((r) => (
                <tr key={r.task}>
                  <td>{r.task}</td>
                  <td>{mark(r.old)}</td>
                  <td>{mark(r.new)}</td>
                  <td className="num">{cost(r.costOld)}</td>
                  <td className="num">{cost(r.costNew)}</td>
                  <td>{r.excluded ?? ""}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
      {summary && (
        <>
          <p>{summary.wording}</p>
          {summary.skipped > 0 && <p className="meta">{summary.skipped} malformed rows were skipped.</p>}
        </>
      )}
    </>
  );
}

// F15: loadForward validates forward.json rows; readForward/readBacklogSha handle absent files.
import { afterEach, describe, expect, test } from "bun:test";
import { mkdtempSync, mkdirSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { loadForward, readBacklogSha, readForward } from "../web/lib/forward.ts";

const good = { task: "F01", old: true, new: false, costOld: 1.5, costNew: null };

describe("loadForward", () => {
  test("non-objects give the empty state", () => {
    for (const v of [null, undefined, 3, "x", [], {}, { rows: "no" }]) {
      expect(loadForward(v)).toEqual({ rows: [], summary: null });
    }
  });

  test("keeps good rows and the verbatim wording", () => {
    const r = loadForward({ rows: [good, { ...good, task: "F02", excluded: "invalidated" }], summary: { n: 2, wording: "No difference  yet." } });
    expect(r.rows.length).toBe(2);
    expect(r.rows[1]!.excluded).toBe("invalidated");
    expect(r.summary).toEqual({ n: 2, wording: "No difference  yet.", skipped: 0 });
  });

  test("skips malformed rows and counts them", () => {
    const bad = [null, "x", { ...good, task: 5 }, { ...good, old: "yes" }, { ...good, costNew: "1" }, { ...good, costOld: -1 }, { ...good, excluded: 3 }];
    const r = loadForward({ rows: [good, ...bad], summary: { n: 1, wording: "w" } });
    expect(r.rows).toEqual([good]);
    expect(r.summary?.skipped).toBe(bad.length);
  });

  test("a malformed summary is null", () => {
    expect(loadForward({ rows: [good], summary: { n: "1", wording: "w" } }).summary).toBeNull();
    expect(loadForward({ rows: [good] }).summary).toBeNull();
  });
});

describe("file readers", () => {
  let dir = "";
  afterEach(() => rmSync(dir, { recursive: true, force: true }));

  test("absent files", () => {
    dir = mkdtempSync(join(tmpdir(), "fwd-"));
    expect(readForward(dir)).toEqual({ rows: [], summary: null });
    expect(readBacklogSha(dir)).toBeNull();
  });

  test("present files; broken JSON is empty", () => {
    dir = mkdtempSync(join(tmpdir(), "fwd-"));
    mkdirSync(join(dir, "self"));
    writeFileSync(join(dir, "self", "forward.json"), JSON.stringify({ rows: [good], summary: { n: 1, wording: "w" } }));
    writeFileSync(join(dir, "self", "prereg.json"), JSON.stringify({ backlog_sha256: "abc123" }));
    expect(readForward(dir).rows).toEqual([good]);
    expect(readBacklogSha(dir)).toBe("abc123");
    writeFileSync(join(dir, "self", "forward.json"), "{nope");
    expect(readForward(dir)).toEqual({ rows: [], summary: null });
  });
});
